// Typed access to the mapgen-server API. The types come from the Rust
// definitions (generated by ts-rs into ./types), so a server change that the
// front-end does not follow fails `npm run check`.
import type { ApiError } from './types/ApiError';
import type { FormSpec } from './types/FormSpec';
import type { JobCreated } from './types/JobCreated';
import type { JobStatus } from './types/JobStatus';
import type { PresetInfo } from './types/PresetInfo';
import type { WorldMetadata } from './types/WorldMetadata';
import type { WorldRequest } from './types/WorldRequest';
import type { WorldSummary } from './types/WorldSummary';

/** An API call that failed, with the server's message. */
export class ApiFailure extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = 'ApiFailure';
  }
}

function isApiError(body: unknown): body is ApiError {
  return typeof body === 'object' && body !== null && typeof (body as ApiError).error === 'string';
}

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, init);
  if (!response.ok) {
    const body: unknown = await response.json().catch(() => null);
    throw new ApiFailure(response.status, isApiError(body) ? body.error : response.statusText);
  }
  // The server produces these bodies from the same types: trusted shape.
  return (response.status === 204 ? undefined : await response.json()) as T;
}

export const api = {
  presets: () => call<PresetInfo[]>('/api/presets'),
  form: () => call<FormSpec>('/api/form'),
  worlds: () => call<WorldSummary[]>('/api/worlds'),
  createWorld: (request: WorldRequest) =>
    call<JobCreated>('/api/worlds', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(request),
    }),
  deleteWorld: (id: string) => call<void>(`/api/worlds/${encodeURIComponent(id)}`, { method: 'DELETE' }),
  metadata: (id: string) => call<WorldMetadata>(worldFile(id, 'raw_data/world.json')),
};

/** URL of a file of a generated world. */
export function worldFile(id: string, path: string): string {
  return `/worlds/${encodeURIComponent(id)}/${path}`;
}

const STATUSES: ReadonlySet<string> = new Set(['queued', 'running', 'done', 'failed']);

function isJobStatus(value: unknown): value is JobStatus {
  return (
    typeof value === 'object' &&
    value !== null &&
    STATUSES.has((value as { status?: unknown }).status as string)
  );
}

/**
 * Follows a generation job until it finishes. Calls `onStatus` for every
 * update; resolves with the final status. The returned `cancel` stops listening.
 */
export function followJob(
  jobId: string,
  onStatus: (status: JobStatus) => void,
): { done: Promise<JobStatus>; cancel: () => void } {
  const source = new EventSource(`/api/jobs/${encodeURIComponent(jobId)}/events`);
  const done = new Promise<JobStatus>((resolve) => {
    source.onmessage = (event: MessageEvent<string>) => {
      const parsed: unknown = JSON.parse(event.data);
      if (!isJobStatus(parsed)) {
        return;
      }
      onStatus(parsed);
      if (parsed.status === 'done' || parsed.status === 'failed') {
        source.close();
        resolve(parsed);
      }
    };
    source.onerror = () => {
      // The server closes the stream after the final status; anything else is a lost connection.
      if (source.readyState === EventSource.CLOSED) {
        resolve({ status: 'failed', error: 'lost the connection to the server' });
      }
    };
  });
  return { done, cancel: () => source.close() };
}
